import itertools
import math

def calculate_E(a, b, c):
    S = a + b + c
    P2 = a*b + b*c + c*a
    numerator = S * (P2 + 1)
    denominator = 4 * a * b * c

    # Check if it is an integer
    if numerator % denominator == 0:
        return numerator // denominator
    else:
        return None

# Brute force search for 1 <= a < b < c <= 7
upper_bound = 7
valid_n_values = set()

for a in range(1, upper_bound + 1):
    for b in range(a + 1, upper_bound + 1):
        for c in range(b + 1, upper_bound + 1):
            n = calculate_E(a, b, c)
            if n is not None:
                valid_n_values.add(n)

print("Found integer values of n:")
print(sorted(list(valid_n_values)))

